/* Lot 108: relative colours (rgb(), hsl(), oklab(), oklch() from an origin) (generated by scripts/lot108_gen.py; expectations from scripts/lot108_model.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_cssprop.h"

static char g_o[64];

/* 1, the 24-bit colour and the alpha (0..255) the reader paints, or 0 */
static const char *col(const char *v) {
    unsigned int rgb = 0;
    int a = 0;
    if (!wf_cssprop_color(v, (int)strlen(v), &rgb, &a)) return "0";
    snprintf(g_o, sizeof(g_o), "1 %06x %d", rgb, a);
    return g_o;
}

static void test_l108_rel_0(void) {
    TEST_ASSERT_EQUAL_STRING("1 ffffff 255", col("oklch(from oklab(1 0.05 200) l calc(C / 8) calc(h + 45))"));
    TEST_ASSERT_EQUAL(1, wf_cssprop_match(WF_CSSPROP_COLOR, "oklch(from oklab(1 0.05 200) l calc(C / 8) calc(h + 45))"));
    TEST_ASSERT_EQUAL_STRING("1 ffeef6 255", col("hsla(from rgb(22 51 251 / 120%) -30 calc((s + h) / 2) s / alpha)"));
    TEST_ASSERT_EQUAL(1, wf_cssprop_match(WF_CSSPROP_COLOR, "hsla(from rgb(22 51 251 / 120%) -30 calc((s + h) / 2) s / alpha)"));
    TEST_ASSERT_EQUAL_STRING("1 000000 255", col("rgba(from black calc(r / 4) calc(r) b / alpha)"));
    TEST_ASSERT_EQUAL(1, wf_cssprop_match(WF_CSSPROP_COLOR, "rgba(from black calc(r / 4) calc(r) b / alpha)"));
    TEST_ASSERT_EQUAL_STRING("1 4500ff 255", col("hsla(from oklab(0 0 -0.1) h h 50)"));
    TEST_ASSERT_EQUAL(1, wf_cssprop_match(WF_CSSPROP_COLOR, "hsla(from oklab(0 0 -0.1) h h 50)"));
    TEST_ASSERT_EQUAL_STRING("1 413200 255", col("oklab(from lch(60 40 120) calc(l / 2) a l)"));
    TEST_ASSERT_EQUAL(1, wf_cssprop_match(WF_CSSPROP_COLOR, "oklab(from lch(60 40 120) calc(l / 2) a l)"));
    TEST_ASSERT_EQUAL_STRING("1 000000 255", col("hsla(from hsl(from gainsboro calc(h) calc(s) s) h calc(s * 0) -10)"));
    TEST_ASSERT_EQUAL(1, wf_cssprop_match(WF_CSSPROP_COLOR, "hsla(from hsl(from gainsboro calc(h) calc(s) s) h calc(s * 0) -10)"));
    TEST_ASSERT_EQUAL_STRING("1 000000 255", col("HSLA(from white h 0 calc(s * 3))"));
    TEST_ASSERT_EQUAL(1, wf_cssprop_match(WF_CSSPROP_COLOR, "HSLA(from white h 0 calc(s * 3))"));
    TEST_ASSERT_EQUAL_STRING("0", col("hsl(from rgb(17%, 142, 4%) 0.5turn calc(s + 30deg) -10)"));
    TEST_ASSERT_EQUAL(0, wf_cssprop_match(WF_CSSPROP_COLOR, "hsl(from rgb(17%, 142, 4%) 0.5turn calc(s + 30deg) -10)"));
    TEST_ASSERT_EQUAL_STRING("1 77000d 221", col("rgba(from #7e8d r none 12.5)"));
    TEST_ASSERT_EQUAL(1, wf_cssprop_match(WF_CSSPROP_COLOR, "rgba(from #7e8d r none 12.5)"));
    TEST_ASSERT_EQUAL_STRING("1 20ffff 128", col("rgb(from white calc(r / 8) g r / 0.5)"));
    TEST_ASSERT_EQUAL(1, wf_cssprop_match(WF_CSSPROP_COLOR, "rgb(from white calc(r / 8) g r / 0.5)"));
}

